RG.RANGES = [{"n":"四国山地","q":"Q1093753","wp":"四国山地","pts":[[33.2307,132.6012],[33.5215,132.5939],[33.4071,132.7647],[33.5888,132.8156],[33.5588,132.955],[33.6612,133.0033],[33.8476,133.0054],[33.6723,133.1682],[33.7939,133.2067],[33.8049,133.3038],[33.7567,133.3964],[33.8253,133.4624],[33.8849,133.5477],[33.8822,133.6354],[33.861,133.7316],[33.891,133.8284],[33.9275,133.907],[33.8424,134.0327],[33.861,134.1216],[33.9101,134.1826],[33.9206,134.2694],[33.8852,134.4008],[33.9988,134.4488]],"d":"四国山地（しこくさんち）は、四国の中央部を東西に貫く山地。中央構造線の南に千数百メートル級の急峻な山々が連なっている。 範囲は、中央構造線より南側の四国全域に亘る。西南日本内帯に属する讃岐山脈や高縄山地は通常、四国山地に含めない。","img":"Ishizuchi%20Mountains.jpg","k":"山地","m":127,"hi":"二ノ森","he":1929},{"n":"丹沢山地","q":"Q493093","wp":"丹沢山地","pts":[[35.4082,138.9168],[35.4233,138.93],[35.4442,138.9446],[35.4019,138.9661],[35.4637,138.9785],[35.454,138.9926],[35.4758,139.01],[35.4549,139.0232],[35.465,139.0353],[35.4983,139.0467],[35.4765,139.0634],[35.4708,139.0818],[35.4645,139.1033],[35.4584,139.1169],[35.468,139.1341],[35.4754,139.1467],[35.473,139.1619],[35.4727,139.1784],[35.4474,139.2016],[35.4964,139.206],[35.4638,139.2268],[35.504,139.2354],[35.5258,139.2503],[35.5126,139.2669]],"d":"丹沢山地（たんざわ さんち）は、神奈川県北西部から山梨県東部にかけて広がる山地である。東西約40キロメートル、南北約20キロメートルに及び、神奈川県の面積の約6分の1を占める。本項で扱う丹沢山地の最高峰は標高1,673メートルの蛭ヶ岳である。丹沢山地を関東山地に含めるかどうかは文献によって異なる。","img":"Tanzawa%20mountains%20from%20yokohama.JPG","k":"山地","m":97,"hi":"蛭ヶ岳","he":1673},{"n":"日高山脈","q":"Q475451","wp":"日高山脈","pts":[[43.1109,142.6975],[43.0385,142.729],[42.9606,142.6544],[42.9464,142.7195],[42.9017,142.7293],[42.8394,142.702],[42.7947,142.742],[42.7498,142.7145],[42.7099,142.783],[42.6353,142.6906],[42.6107,142.7714],[42.5538,142.7812],[42.5271,142.8223],[42.4735,142.8494],[42.4378,142.9095],[42.4147,142.9568],[42.3718,142.9939],[42.3297,143.0429],[42.3,143.0654],[42.2886,143.2369],[42.2317,143.1653],[42.1448,143.0892],[42.0922,143.141],[42.07,143.2301]],"d":"日高山脈（ひだかさんみゃく）は、北海道の中央南部にある唯一の山脈。狩勝峠側の佐幌岳から襟裳岬までを南北に貫いている。長さは南北およそ150 km、最高峰は幌尻岳で標高2,053 mである。山域の245,668 haが日高山脈襟裳十勝国立公園に指定されている。","img":"Hidaka%20Mountains%20modified.jpg","k":"山脈","m":96,"hi":"幌尻岳","he":2053},{"n":"奥羽山脈","q":"Q1357388","wp":"奥羽山脈","pts":[[37.3334,140.0565],[37.4932,140.1476],[37.6559,140.2636],[37.8337,140.3094],[38.0404,140.3614],[38.1985,140.4687],[38.3853,140.6099],[38.6281,140.5487],[38.7235,140.5921],[38.9611,140.7889],[39.1127,140.8666],[39.3226,140.7238],[39.4903,140.7885],[39.6795,140.9369],[39.8061,140.8811],[40.0256,140.8324],[40.1792,140.9218],[40.3897,140.7518],[40.6589,140.8772],[40.8404,141.0395]],"d":"奥羽山脈（おううさんみゃく）は、日本の東北地方の中央部を南北に貫く山脈。青森県の夏泊半島から福島県・栃木県境の帝釈山地に至る全長約500キロメートルの脊梁山脈である。","img":"Ou%20mountains%20koriyama.jpg","k":"山脈","m":64,"hi":"岩手山","he":2038},{"n":"中国山地","q":"Q857567","wp":"中国山地","pts":[[34.3147,131.3792],[34.2489,131.5322],[34.4504,131.7467],[34.4778,131.9663],[34.5365,132.1055],[34.5782,132.2423],[34.9531,132.7279],[35.0875,132.8544],[35.0612,133.06],[35.1684,133.2516],[35.2186,133.504],[35.314,133.5893],[35.2902,133.7828],[35.3445,133.9591],[35.2798,134.1608],[35.2206,134.4291],[35.2798,134.5819],[35.0816,134.9133]],"d":"中国山地（ちゅうごくさんち）は、本州の西端部に当たる、中国地方の脊梁を為す山地である。なお、中国地方最高峰の大山や、その外輪山の蒜山、および三瓶山は、中国山地より北に外れて出来た独立峰の火山であり、これらは他の中国山地の山々とは生成過程が大きく異なる山だが、国土地理院では中国山地中部と分類している。 山々は東西に長く連なっており、東はおよそ市川・円山川（いずれも兵庫県）付近から、西は響灘海岸（山口県西岸）までの約500 kmに及ぶ。氷ノ山（標高1510 m）を除くと、高い山でも標高約1300 mから1000 m程度に過ぎず、その他は、おおむね標高約500 mから200 m程度の比較的低い山で構成されている。","img":"Hyonosen01s1600.jpg","k":"山地","m":63,"hi":"大山","he":1729},{"n":"飛騨山脈","q":"Q1072070","wp":"飛騨山脈","pts":[[36.0392,137.6022],[36.113,137.5577],[36.1808,137.5306],[36.1971,137.5781],[36.2379,137.6108],[36.2907,137.6087],[36.342,137.6279],[36.3986,137.5975],[36.4382,137.6124],[36.4821,137.7229],[36.5526,137.6213],[36.5711,137.6409],[36.6347,137.6925],[36.6876,137.6729],[36.7583,137.7917],[36.8783,137.7303],[36.9331,137.7163]],"d":"飛驒山脈（ひださんみゃく）は、富山県、新潟県、岐阜県、長野県に跨って連なる山脈。通称は北アルプスで、木曽山脈（中央アルプス）や赤石山脈（南アルプス）と共に日本アルプスを構成する山々である。 山脈の主要部分は、中部山岳国立公園に指定されている。山脈の最高峰は、標高3,190mの奥穂高岳で、富士山と北岳に次いで日本で3番目に高い山である。","img":"%E7%99%BD%E9%A6%AC%E5%A4%A7%E6%A9%8B%E3%81%8B%E3%82%89%E3%81%AE%E5%8C%97%E3%82%A2%E3%83%AB%E3%83%97%E3%82%B9%E3%81%A8%E3%81%A9%E3%82%93%E3%81%90%E3%82%8A%E5%9C%B0%E5%8C%BA%E3%81%AE%E6%A1%9C.jpg","k":"山脈","m":62,"hi":"穂高岳","he":3190},{"n":"奥秩父山塊","q":"Q1738280","wp":"奥秩父山塊","pts":[[35.7796,138.5391],[35.7542,138.5919],[35.7583,138.6047],[35.8933,138.5919],[35.8592,138.636],[35.8666,138.6684],[35.8321,138.7124],[35.8957,138.7304],[35.9343,138.7385],[35.8571,138.8099],[35.9238,138.8222],[35.8627,138.8876],[36.0236,138.8392],[35.8553,138.9436],[35.9294,138.9478],[35.9614,138.9714],[35.8939,139.0461],[35.9517,139.0978]],"d":"奥秩父山塊（おくちちぶさんかい）とは、東京、埼玉、山梨、長野の1都3県にまたがる山塊である。野辺山高原の南東に位置する飯盛山（1643メートル）から雲取山（2017メートル）および南は三窪高原まで、広くはそれに東は奥多摩エリア、北は両神山（1723メートル）付近、南は大菩薩連嶺までを加えた山塊で関東山地の中心部をなす。奥秩父山地（おくちちぶさんち）ともいう。 千曲川（信濃川上流）、荒川、笛吹川（富士川上流）、多摩川の4河川の水源域であり、山域に火山を含まないことも特徴となっている。","img":"Mt.Asahidake%20and%20Mt.Kokushidake%20and%20Mt.Kitaokusenjodake%20from%20Mt.Kinpu%2002.jpg","k":"山々","m":61,"hi":"北奥千丈岳","he":2601},{"n":"赤石山脈","q":"Q415350","wp":"赤石山脈","pts":[[34.9333,138.303],[35.1261,138.0354],[35.1967,138.0292],[35.2226,138.0565],[35.2756,138.1159],[35.3381,138.0839],[35.3782,138.1431],[35.4507,138.1077],[35.4872,138.1785],[35.5554,138.1681],[35.6123,138.2509],[35.6548,138.2436],[35.7239,138.2357],[35.7684,138.2233],[35.8143,138.2535],[35.934,138.1481]],"d":"赤石山脈（あかいしさんみゃく）は、長野県、山梨県、静岡県に跨って連なる山脈。通称は南アルプスで、飛驒山脈（北アルプス）や木曽山脈（中央アルプス）と共に日本アルプスを構成する山々である。 鋸岳から光岳に及び、この区間の主稜線には登山道が整備され、要所には山小屋とキャンプ指定地がある。また、その東の山梨県側は、南アルプス巨摩県立自然公園に指定されている。","img":"20091228%E5%8D%97%E3%82%A2%E3%83%AB%E3%83%97%E3%82%B9A100.jpg","k":"山脈","m":55,"hi":"北岳","he":3193},{"n":"両白山地","q":"Q7385590","wp":"両白山地","pts":[[35.7552,136.4715],[35.7792,136.5185],[35.7817,136.6681],[35.9279,136.4442],[35.9342,136.6014],[35.8736,136.8261],[36.0537,136.5881],[36.06,136.6902],[36.1047,136.6946],[36.1539,136.7618],[36.1828,136.7855],[36.2548,136.7987],[36.2754,136.8188],[36.3451,136.7952],[36.3836,136.8267],[36.4219,136.8947],[36.5474,136.74]],"d":"両白山地（りょうはくさんち）は、岐阜県、富山県、石川県および福井県にまたがる山域。加濃越山地とも称する。白山が主峰の加越山地と、能郷白山を主峰とする越美山地に分かれる。「両白」とは、それぞれの山地を代表する二つの白山を示したものである。","img":null,"k":"山地","m":55,"hi":"七倉山","he":2557},{"n":"木曽山脈","q":"Q1072062","wp":"木曽山脈","pts":[[35.4096,137.6016],[35.4789,137.6295],[35.5357,137.6245],[35.5647,137.7106],[35.6218,137.756],[35.673,137.8],[35.7261,137.8055],[35.7785,137.8203],[35.8481,137.81],[35.913,137.8626],[36.026,137.9097]],"d":"木曽山脈（きそさんみゃく）は、本州の中央部を長野県の木曽谷と伊那谷に跨って南北に連なる木曽川と天竜川に挟まれた山脈。通称は中央アルプスで、飛驒山脈（北アルプス）や赤石山脈（南アルプス）と共に日本アルプスを構成する山々である。","img":"Kiso%20Mountains%20from%20Mount%20Senjo%202004-1-4.jpg","k":"山脈","m":38,"hi":"木曽駒ヶ岳","he":2956},{"n":"大峰山脈","q":"Q11434803","wp":"大峰山脈","pts":[[33.9267,135.8317],[33.9825,135.8983],[34.0144,135.9072],[34.0678,135.8986],[34.1027,135.9192],[34.1364,135.8863],[34.1785,135.9041],[34.2125,135.942],[34.2453,135.9298],[34.2744,135.9617],[34.3389,135.8846]],"d":"大峰山脈（おおみねさんみゃく）は八経ヶ岳を最高峰とする紀伊山地の脊梁をなす山脈。「近畿の屋根」や「大和アルプス」とも称される山岳地帯である。 広義の大峰山は大峰山脈を指す場合もあり、深田久弥の『日本百名山』の「大峰山」は大峰山脈全般に亘って記述されている。東西は熊野川上流の十津川と支流の北山川に挟まれ、北は中央構造線に沿う紀ノ川上流の吉野川に接する。","img":"Mount%20Hakkyo%20and%20Mount%20Misen.jpg","k":"山脈","m":35,"hi":"八経ヶ岳","he":1915},{"n":"紀伊山地","q":"Q863186","wp":"紀伊山地","pts":[[33.7741,135.471],[33.7267,135.7133],[33.9317,135.7092],[34.1924,135.7211],[34.2318,135.8381],[34.3172,135.9893],[34.4328,136.7485]],"d":"紀伊山地（きいさんち）は、紀伊半島のうち中央構造線以南の大半を占める山地。侵食が著しいため、険しい地形がよく発達している。三重県、奈良県、和歌山県にまたがっている。脊梁の方向はおおむね北東-南西に走り、1500m前後の尾根が連なる。","img":"Mount%20Odaigahara%20around%20Daijagura.jpg","k":"山地","m":31,"hi":"龍神岳","he":1382},{"n":"越後山脈","q":"Q4532970","wp":"越後山脈","pts":[[36.8351,138.904],[36.9613,139.0752],[37.0786,139.1251],[37.3063,139.2586],[37.5219,139.4259],[37.6606,139.5775],[38.2608,139.9222]],"d":"越後山脈（えちごさんみゃく）は、狭義には新潟県と福島県の県境付近にある標高600メートルから2100メートルの山地。越後山地と呼ばれることもあるが、国土地理院の地図では越後山脈である。広義には山形県、新潟県、福島県、群馬県、長野県にまたがる脊梁山脈を指す。一部は磐梯朝日国立公園や尾瀬国立公園に含まれる。","img":"%E9%8A%80%E5%B1%B1%E5%B9%B3%E3%81%8B%E3%82%89%E6%9C%9B%E3%82%80%E8%B6%8A%E5%BE%8C%E9%A7%92%E3%83%B6%E5%B2%B3.JPG","k":"山脈","m":31,"hi":"至仏山","he":2228},{"n":"立山連峰","q":"Q11597842","wp":"立山連峰","pts":[[35.5706,137.6067],[36.4406,137.5112],[36.5662,137.5663],[36.7219,137.589]],"d":"立山連峰（たてやまれんぽう）は、飛騨山脈（北アルプス）の北部、黒部川の西岸に連なる山域の群峰。東岸の後立山連峰と双対する雄大な群峰・連峰群である。中部山岳国立公園の一部となっている。","img":"Tsurugidake%20from%20bessan%2022%201995%208%2020.jpg","k":"連峰","m":30,"hi":"立山","he":3015},{"n":"北上山地","q":"Q4222434","wp":"北上山地","pts":[[38.5011,141.3586],[38.9473,141.4148],[39.2319,141.6121],[39.3704,141.6095],[39.5883,141.5116],[39.7936,141.4656],[40.0861,141.5029]],"d":"北上山地（きたかみさんち）は、 岩手県中央部を北から南に流れ宮城県東部の石巻市で海に注ぐ「北上川」の東側に位置する山地。大部分は岩手県に属し、山地の東側は太平洋に面しリアス式海岸を形成している。最高峰は岩手県の早池峰山（標高1917m）で日本百名山の一つである。国土地理院地図や学校教育では、北上高地と呼ばれる。","img":"Mt%20Hayachine.jpg","k":"山地","m":25,"hi":"早池峰山","he":1917},{"n":"後立山連峰","q":"Q11488366","wp":"後立山連峰","pts":[[36.5439,137.6872],[36.6064,137.7489],[36.673,137.7129],[36.7768,137.7649],[36.8192,137.7826],[36.9024,137.7225],[36.9687,137.7029]],"d":"後立山連峰（うしろたてやまれんぽう）は、飛騨山脈（北アルプス）の北部が、造山過程で裂けて黒部川が流れ、この東岸に連なる連峰群。西岸の立山連峰と双対している。","img":"20070528KitaAlpsNishinaSanKoTagged.jpg","k":"連峰","m":25,"hi":"鹿島槍ヶ岳","he":2889},{"n":"石狩山地","q":"Q6080245","wp":"石狩山地","pts":[[43.7644,142.4886],[43.6979,142.8657],[43.5897,142.9235],[43.5742,143.0467],[43.4567,143.0325],[43.4394,143.1443],[43.3413,143.2493]],"d":"石狩山地（いしかりさんち）は、北海道のほぼ中央部にある山地。狭義には石狩中央山地を、広義には周囲の大雪火山群、十勝岳火山群、然別火山群を含めた山群を指す。","img":"Mount%20Ishikari%20from%20Nipesotsu-Maruyama%20Volcanic%20Group%202005-08-17.jpg","k":"山地","m":24,"hi":"大雪山","he":2290},{"n":"鈴鹿山脈","q":"Q7651163","wp":"鈴鹿山脈","pts":[[34.8711,136.3228],[34.9161,136.3681],[34.9963,136.3989],[35.041,136.4278],[35.1099,136.4096],[35.1789,136.4297],[35.2536,136.4079]],"d":"鈴鹿山脈（すずかさんみゃく）は、岐阜県及び三重県と滋賀県との県境沿いに位置する山脈。一般的には関ヶ原の南に位置する霊仙山から鈴鹿峠までの範囲を指す。南端の定義は、油日岳とするなどの諸説がある。","img":"Mount%20Gozaisho%20from%20Mount%20Amagoi%202009-10-11.jpg","k":"山脈","m":21,"hi":"御池岳","he":1247},{"n":"白神山地","q":"Q501638","wp":"白神山地","pts":[[40.5371,140.0043],[40.4731,140.1125],[40.4669,140.203],[40.4392,140.2845],[40.4286,140.4089],[40.4361,140.5897]],"d":"白神山地（しらかみさんち）は、青森県から秋田県にまたがる山地帯の総称。屋久島とならんで1993年（平成5年）12月、日本で初めてのユネスコ世界遺産（自然遺産）に登録された。そこには「人の影響をほとんど受けていない原生的なブナ天然林が世界最大級の規模で分布」（世界遺産登録理由）と記されている。","img":"Sirakami%20santi.JPG","k":"山地","m":20,"hi":"向白神岳","he":1250},{"n":"六甲山地","q":"Q11392466","wp":"六甲山地","pts":[[34.6467,135.0982],[34.7072,135.1737],[34.7176,135.1915],[34.7752,135.2767]],"d":"六甲山地（ろっこうさんち）は、兵庫県南東部に位置する山地。六甲山系と丹生山系からなり、瀬戸内海国立公園の区域に指定されている。六甲連山とも。 六甲山系、六甲最高峰は六甲山を参照のこと。","img":"Amsterdam%20at%20Kobe10s3872.jpg","k":"山地","m":19,"hi":"六甲山","he":931},{"n":"讃岐山脈","q":"Q7420745","wp":"讃岐山脈","pts":[[34.0663,133.7764],[34.1154,133.994],[34.1452,134.1784],[34.1564,134.332],[34.1818,134.5145]],"d":"讃岐山脈（さぬきさんみゃく）は、香川県と徳島県の境界に位置する地塁山脈。","img":"Mt.Ryuosan.jpg","k":"山脈","m":17,"hi":"竜王山","he":1060},{"n":"北見山地","q":"Q8191765","wp":"北見山地","pts":[[44.9504,142.3162],[44.5631,142.5478],[44.3301,142.9576],[44.0574,143.011],[43.8416,143.271]],"d":"北見山地（きたみさんち）は、北海道北東部をほぼ南北に走る山地。上川総合振興局とオホーツク総合振興局の境界に沿うように連なる。天塩山地、石狩山地、夕張山地、日高山脈などとともに北海道の南北に貫く蝦夷山系をなしている。 天塩川のつくる盆地列の東に並ぶ山地で、北海道のオホーツク海側と日本海側を分ける分水嶺となっている。","img":"Mount%20Teshio.JPG","k":"山地","m":17,"hi":"天塩岳","he":1558},{"n":"台高山脈","q":"Q11412093","wp":"台高山脈","pts":[[34.4128,136.0833],[34.3415,136.0862],[34.1933,136.0942],[34.0587,136.1724]],"d":"台高山脈（だいこうさんみゃく）は、紀伊半島東部に位置する山脈。大台ヶ原山地（おおだいがはらさんち）とも言う。 三重県と奈良県の境を成し、標高1,000～1,600m級の山々が連なる。大峰山脈と共に「近畿の屋根」と称されるほか、「近畿の秘境」・「三重県の屋根」の異名を持つ。","img":"Azami05.JPG","k":"山脈","m":16,"hi":"大台ヶ原山","he":1695},{"n":"金剛山地","q":"Q11646528","wp":"金剛山地","pts":[[34.4019,135.6654],[34.4498,135.682],[34.5112,135.6782],[34.5518,135.6552]],"d":"金剛山地（こんごうさんち）は、大阪平野と奈良盆地を隔てる丘陵性の山地。主峰は金剛山である。北の生駒山地とあわせて金剛・生駒山地と呼ばれることもある。これらの山は河内国と大和国との国境、大阪府と奈良県の府県境のそれぞれ一部をなしている。","img":"Kongousanchi20101012.JPG","k":"山地","m":15,"hi":"金剛山","he":1125},{"n":"和泉山脈","q":"Q11417784","wp":"和泉山脈","pts":[[34.2919,135.1443],[34.304,135.217],[34.3359,135.3742],[34.3819,135.5496]],"d":"和泉山脈（いずみさんみゃく）とは、大阪府と和歌山県とを隔てる山脈。大阪盆地の南西部に位置し東西に連なる。","img":null,"k":"山脈","m":15,"hi":"南葛城山","he":922},{"n":"剣山地","q":"Q11397904","wp":"剣山地","pts":[[33.8519,133.7075],[33.8247,133.9903],[33.9025,134.1285],[33.8993,134.3759],[33.9799,134.5196]],"d":"剣山地（つるぎさんち）は四国山地東部に属する剣山を最高峰とする山地である。北は御荷鉾構造線、南は那賀川に沿う仏像構造線に挟まれ、南北幅15から25km、東西約60kmに及ぶ。","img":"Tsurugi%20Mountains.jpg","k":"山地","m":15,"hi":"剣山","he":1955},{"n":"北摂山系","q":"Q11401749","wp":"北摂山系","pts":[[35.0008,135.3776],[34.9739,135.4768],[34.8849,135.461],[34.9015,135.5282],[34.8941,135.6128]],"d":"北摂山系（ほくせつさんけい）は、主に兵庫県南東部から大阪府北部、京都府南西部に広がる山地で、丹波高地の南部を含む区域であり、北摂山地と称される場合もある。","img":"Kenpisan02.JPG","k":"山系","m":15,"hi":"深山","he":791},{"n":"飛騨高地","q":"Q11665923","wp":"飛騨高地","pts":[[35.934,136.998],[36.2272,136.9397],[36.3108,136.9658],[36.4163,137.0664]],"d":"飛騨高地（ひだこうち）は、岐阜県と富山県にまたがる高原状の山地。中央に高山盆地がある。飛騨山地、飛騨高原とも呼ばれる。 岐阜県北部の飛騨地方を中心に、北は富山県南部、南は美濃地方北部まで広がる標高1,000 m級の高地。","img":"Sarugabanbayama%20from%20Nodanisyojiyama%202010-4-18.JPG","k":"高地","m":13,"hi":"猿ヶ馬場山","he":1875},{"n":"夕張山地","q":"Q6149420","wp":"夕張山地","pts":[[42.8504,142.255],[43.0997,142.251],[43.237,142.2697]],"d":"夕張山地（ゆうばりさんち）とは、北海道のほぼ中央にそびえる山地（山塊）。最高峰は山地北部に位置する芦別岳である。夕張山脈ともいう。","img":"Mt.Ashibetsu.JPG","k":"山地","m":12,"hi":"シューパロ岳","he":1493},{"n":"常念山脈","q":"Q11481387","wp":"常念山脈","pts":[[36.2304,137.6433],[36.2847,137.7324],[36.3418,137.7218],[36.4152,137.7394]],"d":"常念山脈（じょうねんさんみゃく）は、飛騨山脈（北アルプス）のうち主稜線の東側に平行して南北に延びる山域の総称。主稜線との間に高瀬川、梓川が流れる。主稜線とは大天井岳から槍ヶ岳への東鎌尾根の稜線でつながっており、中房温泉から燕岳を経てこの稜線へ至る登山道は表銀座と呼ばれている。1934年（昭和9年）12月4日 に山域が、中部山岳国立公園に指定された。","img":"Mount%20Yokotoshi%20and%20Mount%20Onensho%20from%20Mount%20Jonen%20%281999-08-01%29.jpg","k":"山脈","m":12,"hi":"常念岳","he":2857},{"n":"生駒山地","q":"Q11574917","wp":"生駒山地","pts":[[34.624,135.6599],[34.6721,135.6752],[34.7947,135.7239]],"d":"生駒山地（いこまさんち）は、大阪平野と京都盆地・奈良盆地とを隔てる丘陵性の山地。主峰は生駒山である。南の金剛山地とあわせて金剛・生駒山地と呼ばれることもある。これらの山は河内国と山城国・大和国との国境、大阪府と京都府・奈良県の府県境のそれぞれ一部をなしている。","img":"JP-29%20Mount%20Ikoma%20skyline.jpg","k":"山地","m":11,"hi":"生駒山","he":642},{"n":"北八ヶ岳","q":"Q7059149","wp":"北八ヶ岳","pts":[[36.0943,138.3117],[36.0687,138.3466],[36.0247,138.3621]],"d":"北八ヶ岳（きたやつがたけ）は、八ヶ岳連峰の北部、フォッサマグナの中央部を占める大規模複成火山体である八ヶ岳火山列のうちの、北側を指す。「きたやつ」と略される。一般的に北八ヶ岳とは大河原峠から南の夏沢峠までをいう。全域が長野県に属する。","img":"Kita-Yatsugatake.jpg","k":"山々","m":11,"hi":"天狗岳","he":2646},{"n":"脊振山地","q":"Q11612199","wp":"脊振山地","pts":[[33.4693,130.1143],[33.4786,130.2233],[33.4287,130.4236]],"d":"脊振山地（せふりさんち）は、九州の北部、福岡県と佐賀県の県境にまたがる山地。筑紫山地の一部をなす。脊振山系（せふりさんけい）ともいう。","img":"Sefuri02.JPG","k":"山地","m":10,"hi":"脊振山","he":1055},{"n":"霧島山","q":"Q1319361","wp":"霧島山","pts":[[31.9599,130.828],[31.9381,130.8691],[31.8938,130.9051]],"d":"霧島山（きりしまやま）は、九州南部の宮崎県と鹿児島県県境付近に広がる火山群の総称。霧島連山、霧島連峰、霧島山地あるいは霧島火山群とも呼ばれる。","img":"Kirishima%20volcano%2020111125.jpg","k":"山々","m":10,"hi":"韓国岳","he":1700},{"n":"静浦山地","q":"Q11663639","wp":"静浦山地","pts":[[35.0753,138.8904],[35.0575,138.9066],[35.01,138.918]],"d":"静浦山地（しずうらさんち）は静岡県の駿河湾奥部の海岸沿いにある山並みの総称。近年では、沼津市南東部に当たる、北端の香貫山から大平山周辺までの山域を、地元の登山愛好会が沼津アルプスと命名し、この名も定着しつつある。 この山地にはシイやカシ類の常緑広葉樹林が分布し、特にウバメガシの純林は日本では北限に当たり、貴重な自然環境が残されている。","img":"Numazu%20Alps%2020100718.jpg","k":"山地","m":9,"hi":"葛城山","he":452},{"n":"八ヶ岳","q":"Q905588","wp":"八ヶ岳","pts":[[35.9457,138.3522],[35.9715,138.3642],[35.9935,138.3645]],"d":"八ヶ岳（やつがたけ、八ケ岳とも表記される）は、諏訪湖の東方にあって長野県から山梨県へと南北に連なる火山。日本百名山の一つ。 「八ヶ岳」は特定の一峰を指して呼ぶ名前ではなく、山梨・長野両県に跨る山々の総称であるが、その範囲は「夏沢峠以南のいわゆる南八ヶ岳のみ」「南八ヶ岳及び北八ヶ岳の領域（蓼科山を除いた領域）」「蓼科山まで含んだ八ヶ岳連峰全体」など様々な定義がある。日本百名山でいう八ヶ岳は南八ヶ岳のみを指す。","img":"Mt.Akadake%20and%20Mt.Amidadake%20from%20Mt.Gongendake%2002.jpg","k":"山々","m":9,"hi":"赤岳","he":2899},{"n":"関東山地","q":"Q10872953","wp":"関東山地","pts":[[36.3321,138.5795],[36.0181,138.8468],[35.5593,139.1854]],"d":"関東山地（かんとうさんち）は、関東平野の西方に位置する地塁山地。広義には丹沢山地や御正体山地を含む山地である。狭義には桂川以北のいわゆる秩父山地を指す。関東平野との間は八王子構造線によって画されているが、関東山地の東麓側には比企丘陵、岩殿丘陵、多摩丘陵などが半島状に分布する。","img":null,"k":"山地","m":9,"hi":null,"he":null},{"n":"三国山脈","q":"Q11354734","wp":"三国山脈","pts":[[36.7796,138.8185],[36.8944,138.9379],[37.0304,139.1339]],"d":"三国山脈（みくにさんみゃく）は、群馬県と新潟県の県境沿いに位置する山脈。 広義の越後山脈のうち、谷川岳周辺の谷川連峰を中心として、西は新潟-長野-群馬県境の白砂山付近から、東は新潟-福島-群馬県境に近い平ヶ岳付近までの山々を指す。上信越高原国立公園、魚沼連峰県立自然公園、越後三山只見国定公園に跨っている。","img":null,"k":"山脈","m":9,"hi":"苗場山","he":2145},{"n":"丹波高地","q":"Q11368591","wp":"丹波高地","pts":[[35.3027,135.0106],[35.0606,135.3026],[35.1764,135.6994]],"d":"丹波高地（たんばこうち）は、兵庫県東部・京都府・大阪府北部・滋賀県西部・福井県南西部に広がる隆起準平原。一般に、由良川と加古川の以東の標高600 mから800 m程度までの類似した標高を有する山岳が林立する地域を指している。丹波山地、或いは丹波高原といわれることもある。高地の内、京都府の綾部市、京丹波町、南丹市、京都市左京区・右京区の範囲が2016年（平成28年）に京都丹波高原国定公園に指定された。","img":null,"k":"高地","m":9,"hi":"皆子山","he":972},{"n":"九重山","q":"Q6921721","wp":"九重山","pts":[[33.0888,131.2441],[33.0889,131.2608],[33.1059,131.2929]],"d":"九重山（くじゅうさん）は、大分県玖珠郡九重町と竹田市久住町の境界に位置する山々の総称（地質学上の呼称）。最高峰は九州本土最高峰でもある中岳（標高1,791m）。 一般的には火山群や周辺地域全体を指すときはくじゅう連山（九重連山）、その主峰となっている一山（標高1,787m）を指す場合には久住山も用いている。国土地理院の火山土地条件図では「くじゅう連山」とひらがな表記になっている。","img":"Kuju-san.JPG","k":"山々","m":9,"hi":"中岳","he":1791},{"n":"比良山地","q":"Q8524042","wp":"比良山地","pts":[[35.2332,135.8923],[35.4116,135.8532],[35.5099,136.0032]],"d":"比良山地 （ひらさんち） は、滋賀県の琵琶湖西岸に連なる山地。最高峰は武奈ヶ岳（ぶながたけ、1,214.4 m）。大部分が琵琶湖国定公園に属し、古くから近江八景の一つ「比良の暮雪」で知られる景勝地。京阪神からの交通の便もよく、登山やスキーに多くの人が訪れる。","img":"Mt.%20Hira-san%2001.jpg","k":"山地","m":9,"hi":"武奈ヶ岳","he":1214},{"n":"秩父山地","q":"Q11596129","wp":"秩父山地","pts":[[35.8976,138.7342],[35.7362,139.1312]],"d":"秩父山地（ちちぶさんち）は、広義の関東山地のうち北側に広がる地塊山地。関東山地のうち相模川以北の部分を指し、おおむね、東は関東平野西端、南は相模川・桂川から笹子峠・甲府盆地北端、西はJR小海線、北は碓氷峠を境界とする（一部の山域を除くこともある）。秩父山系、秩父連山とも呼ばれる。最高峰は北奥千丈岳で、標高は2,601mである。","img":"Okuchichibu%20Mountains%20as%20seen%20from%20Sotochichibu%20Mountains.jpg","k":"山地","m":8,"hi":"大持山","he":1294},{"n":"笠置山地","q":"Q11599956","wp":"笠置山地","pts":[[34.6671,135.8918],[34.5936,135.9057]],"d":"笠置山地（かさぎさんち）は、京都府南東部、滋賀県南西部から奈良県北東部、三重県中西部（上野盆地西側）にある高原状の山地。中央部を木津川が横切っており、狭義には川の南に位置する笠置山を含む大和高原のみを指し、木津川以北は信楽山地として区別する。なお、京都府と奈良県との府県境は木津川より南にある。","img":null,"k":"山地","m":8,"hi":"若草山","he":342},{"n":"房総丘陵","q":"Q5005697","wp":"房総丘陵","pts":[[35.1271,139.9014],[35.2504,139.9497]],"d":"房総丘陵（ぼうそうきゅうりょう）は、千葉県の房総半島中南部に広がる丘陵地帯。令制国の安房国と上総国の丘陵であり、富津岬の南の磯根岬付近から大網白里市北部を結んだ線の南東側を指す。北になるに従い標高が下がり、牛久ー東金崖線で下総台地に接する。","img":"Bousou%20hills.JPG","k":"丘陵","m":8,"hi":"鹿野山","he":379},{"n":"ニセコ連峰","q":"Q11324371","wp":"ニセコ連峰","pts":[[42.9036,140.4694],[42.8867,140.6277]],"d":"ニセコ連峰（にせこれんぽう）は、北海道の西部にある火山群である。 比羅夫から雷電峠までを東西にわたって延びる。長さは東西約25 km、南北 15km。最高峰はニセコアンヌプリで標高1,308.2 m。","img":"NISEKO%20RANGE%201.JPG","k":"連峰","m":7,"hi":"目国内岳","he":1220},{"n":"天塩山地","q":"Q6150215","wp":"天塩山地","pts":[[44.1706,142.0698],[44.4076,142.1124]],"d":"天塩山地（てしおさんち）は、北海道中北部をほぼ南北に走る山地。天塩川西側を走っており、留萌振興局、上川総合振興局、空知総合振興局に跨っている。北見山地、石狩山地、夕張山地、日高山脈などとともに北海道の南北に貫く蝦夷山系をなしている。樹林限界が頂上付近であり地味な山地である。","img":null,"k":"山地","m":7,"hi":"ピッシリ山","he":1032},{"n":"伊吹山地","q":"Q4387713","wp":"伊吹山地","pts":[[35.5338,136.3236],[35.4203,136.5001]],"d":"伊吹山地（いぶきさんち）は、岐阜県と滋賀県にまたがる山地。北は、両白山地に連なる。南は、関ヶ原で一旦低くなった後、鈴鹿山脈へと続いている。この狭窄部は、冬の季節風で濃尾平野に降雪をもたらす原因となっている。","img":"Mount%20Ibuki%20and%20N700%20Series%20Shinkansen.jpg","k":"山地","m":7,"hi":"伊吹山","he":1377},{"n":"白峰南嶺","q":"Q11579655","wp":"白峰南嶺","pts":[[35.5869,138.2394],[35.3445,138.2755]],"d":"白峰南嶺（しらねなんれい）は、赤石山脈の間ノ岳から派生した稜線。西の大井川と東の早川（富士川水系）に挟まれた山域である。白峰三山の南の嶺という意味であるため、三山の南端である農鳥岳は含まない。 北部の広河内岳から黒河内岳（笹山）までの山域は南アルプス国立公園の指定を受けている。","img":"Shiranenanrei%20from%20Mount%20Kannon.jpg","k":"山々","m":6,"hi":"広河内岳","he":2895},{"n":"六甲山","q":"Q462120","wp":"六甲山","pts":[[34.7392,135.2181],[34.8067,135.2988]],"d":"六甲山（ろっこうさん）は、兵庫県南東部、神戸市街地の西から北にかけて位置する山塊。瀬戸内海国立公園六甲地域の一部である。一般に「六甲山」は大小の山を含む六甲山系全域（狭義には中央部から東部）を指し、最高峰は特に六甲（山）最高峰と称される。山域は神戸市のほか、芦屋市、西宮市、宝塚市に属す。","img":"Mt%20rokko01s2816.jpg","k":"山々","m":6,"hi":"長峰山","he":688},{"n":"飯豊山地","q":"Q11666685","wp":"飯豊山地","pts":[[37.8971,139.4888],[37.8294,139.7911]],"d":"飯豊山地（いいでさんち）は、福島県と新潟県、山形県の三県にまたがる山地。 越後山脈の北部にあたり、北に荒川、東に国道121号大峠、南に阿賀川、西に越後平野に囲まれた飯豊山塊を中心とした山地である。 晴れていれば北に朝日山地、東に吾妻連峰、南に会津盆地・那須岳、西に日本海まで望むことができる。最高峰は大日岳の標高2128メートルであり、飯豊本山や北股岳、烏帽子岳、御西岳など2000メートル級の山々が連り飯豊連峰と呼ばれ、磐梯朝日国立公園の一部をなしている。","img":"Mount%20Iide%20Range.JPG","k":"山地","m":6,"hi":"飯豊山","he":2105},{"n":"九州山地","q":"Q11370238","wp":"九州山地","pts":[[32.4452,131.0565],[32.86,131.4781]],"d":"九州山地（きゅうしゅうさんち）は、九州の中央部を北東から南西の方向に貫く山地である。","img":"Mt.Sobo.jpg","k":"山地","m":6,"hi":"祖母山","he":1756},{"n":"増毛山地","q":"Q6783145","wp":"増毛山地","pts":[[43.7,141.4742],[43.5348,141.6355]],"d":"増毛山地（ましけさんち）は、北海道中西部にある山地。樺戸山地ともいう。石狩平野の北方に位置し、西は日本海に面する。主峰および最高峰は、 標高1492mの暑寒別岳である。","img":"Mashike%20Mountains%20%28NNE%20side%29%202009-04-08.jpg","k":"山地","m":6,"hi":"群別岳","he":1376},{"n":"大日連峰","q":"Q11435757","wp":"大日連峰","pts":[[36.6508,137.3819],[36.6151,137.5653]],"d":"大日連峰（だいにちれんぽう）は、飛騨山脈（北アルプス）立山連峰のうち、主稜線から派生して尾根をなす山群。大日連山（だいにちれんざん）ともいう。","img":"Dainichirenpo%20and%20Murodo%20from%20Tateyama%201995-8-20.jpg","k":"連峰","m":6,"hi":"奥大日岳","he":2611},{"n":"竜門山地","q":"Q11598405","wp":"竜門山地","pts":[[34.4958,135.8183],[34.4561,135.9003]],"d":"竜門山地（りゅうもんさんち）は、奈良県内にある奈良盆地と吉野川（紀の川）および宇陀川（宇陀盆地）の間に広がる山地。","img":"Ryuumonsanchi20100929a.JPG","k":"山地","m":5,"hi":"竜門岳","he":904},{"n":"筑摩山地","q":"Q11602829","wp":"筑摩山地","pts":[[36.1737,138.069],[36.1225,138.1554]],"d":"筑摩山地（ちくまさんち）は、長野県のほぼ中央部に位置する山地である。中信地方と東信地方にまたがり、両地方間の交通の障壁となってきた。1976年に三才山トンネルが開通し改善されている。美ヶ原や霧ヶ峰もこの中に含まれる。","img":null,"k":"山地","m":5,"hi":"美ヶ原","he":2034},{"n":"筑紫山地","q":"Q11602923","wp":"筑紫山地","pts":[[33.3969,130.2194],[33.4424,130.8612]],"d":"筑紫山地（つくしさんち、ちくしさんち）は、九州北部の福岡県、佐賀県および長崎県の一部にまたがる山地。大分県、熊本県の一部を含む場合もある。 地形的には準平原化が進んだ後に隆起浸食を受けており、高くても1,000m前後のなだらかな地形である。 筑紫野市に始まり、伊万里市・佐世保市に至る西側で複数山列に分かれる背振・天山の山系は「西海（東シナ海）に『尽きる』」という意味から、佐賀県域では「つくし」山地と呼ばれる。","img":null,"k":"山地","m":5,"hi":"英彦山","he":1199},{"n":"足尾山地","q":"Q11636877","wp":"足尾山地","pts":[[36.4453,139.3581],[36.6608,139.4294]],"d":"足尾山地（あしおさんち）は、群馬県北東部から栃木県南西部にまたがる山地。渡良瀬川の源流地域にあたる山々である。一部は日光国立公園に含まれる。","img":"Lake%20Chuzenji%2011.jpg","k":"山地","m":5,"hi":"皇海山","he":2144},{"n":"頸城山塊","q":"Q11664979","wp":"頸城山塊","pts":[[36.9225,137.9553],[36.9115,138.0721]],"d":"頸城山塊（くびきさんかい）は、関川以西で姫川以東、新潟県と長野県との境に連なる山域の総称。「頸城アルプス」あるいは「妙高連峰」と呼ばれることもある。主要な火打山、妙高山、焼山は「頸城三山」と呼ばれる。","img":"%E5%A7%AB%E5%B7%9D%E3%82%88%E3%82%8A%E6%9C%9B%E3%82%80%E9%A0%B8%E5%9F%8E%E5%B1%B1%E5%A1%8A.JPG","k":"山々","m":5,"hi":"火打山","he":2462},{"n":"出羽山地","q":"Q4171960","wp":"出羽山地","pts":[[38.719,139.9997],[40.0406,140.2097]],"d":"出羽山地（でわさんち）または出羽丘陵（でわきゅうりょう）とは、日本の東北地方にある山地。 奥羽山脈の西側、奥羽山脈と並行するように南北に伸びる山地で、青森県西部から秋田県中央部・山形県中央部を通っている。山地の延長は約250km、最高峰は鳥海山の2,236m。奥羽山脈との間には、横手盆地や新庄盆地などが形作られている。","img":"Mount%20Ch%C5%8Dkai%20%282017-05-19%29%20-%20Flickr.jpg","k":"山地","m":5,"hi":"月山","he":1984},{"n":"伊那山地","q":"Q11380892","wp":"伊那山地","pts":[[35.5599,138.017],[35.8299,138.0515]],"d":"伊那山地（いなさんち）は、南アルプスの西側に平行して南北に延びる標高1,600～1,800mの山域の総称である。伊那谷の人は「伊那山脈」と呼んでいる。その範囲は、諏訪湖の南から、天竜川の佐久間ダム付近にまで及んでおり、地形的には更に天竜川の対岸の弓張山地へと連続している。 南アルプスとの間は日本の最も重要な構造線の一つである中央構造線起源の直線状の谷となっており、谷中を国道152号が通過している。","img":null,"k":"山地","m":5,"hi":"鬼面山","he":1890},{"n":"石鎚山脈","q":"Q11587270","wp":"石鎚山脈","pts":[[33.7498,133.1208],[33.7911,133.2207]],"d":"石鎚山脈（いしづちさんみゃく）は、四国山地の一部であり、四国山地のうち、その北部から北西部に位置し、「石鎚山」を最高峰とする、東西方向に長く延びた山脈である。文献類によっては、「石鎚山地」とも呼ばれる。 この山脈は、愛媛県と高知県の県境にまたがる脊梁をなしており、その北側は、地質境界線、地形的境界線、かつ活断層系でもある「中央構造線」に接しており、高縄半島に接する部分を除く地域は、道前平野などの狭い平野部をあいだにはさんで、瀬戸内海に面している。また南側は、四国山地の、より標高が低い山々へと連なっており、吉野川水系、仁淀川水系となっている。","img":"Ishizuchi%20Mountains%20from%20Mt.Setayama.jpg","k":"山脈","m":4,"hi":"石鎚山","he":1982},{"n":"高見山地","q":"Q11672812","wp":"高見山地","pts":[[34.4414,136.0952],[34.4905,136.2022]],"d":"高見山地（たかみさんち）とは、奈良県と三重県に跨がる山地。奥宇陀山地とも。主峰高見山から東へは標高1,000メートル級の山が連なる。西半分は室生赤目青山国定公園の一部、東半分は赤目一志峡県立自然公園の一部に属する。","img":"Takamisan04.JPG","k":"山地","m":4,"hi":"三峰山","he":1235},{"n":"高清水山地","q":"Q86737580","wp":"高清水山地","pts":[[36.4675,136.9331],[36.5239,136.9764]],"d":"高清水山地（たかしょうずさんち）は、富山県砺波市と南砺市の間にまたがる山地。地元の別名で東山連峰とも言われる。","img":null,"k":"山地","m":4,"hi":"高清水山","he":1145},{"n":"日本アルプス","q":"Q645773","wp":"日本アルプス","pts":[[36.5,137.6],[35.7214,137.9204]],"d":"日本アルプス（にほんアルプス）または中部山岳（ちゅうぶさんがく）とは、本州の中部地方にある以下の3つの山脈の総称である。 飛驒山脈（北アルプス）：富山県・岐阜県・長野県・新潟県の4県にまたがる山脈。最高峰は奥穂高岳。 木曽山脈（中央アルプス）：長野県に存在する山脈。","img":"Hakubarenpou.JPG","k":"山々","m":4,"hi":null,"he":null},{"n":"大菩薩連嶺","q":"Q11438686","wp":"大菩薩連嶺","pts":[[35.7625,138.8239],[35.7168,138.9029]],"d":"大菩薩連嶺（だいぼさつれんれい）は山梨県東部にあり、広く解釈した場合の奥秩父山塊の南端となる連嶺。 鶏冠山（黒川山）を北端とし、大菩薩嶺、大菩薩峠、小金沢山、湯ノ沢峠を経て滝子山に至る、南端はほぼ中央自動車道、甲州街道（国道20号）、JR中央本線に接する山並み。西南部には甲州市がある。","img":"Mts.Daibosatsu%20from%20Mt.Tonodake%2001.jpg","k":"山々","m":4,"hi":"大菩薩嶺","he":2057},{"n":"奥多摩","q":"Q10843518","wp":"奥多摩","pts":[[35.7996,138.9981],[35.8171,139.1285]],"d":"奥多摩（おくたま）とは、東京都西部の山岳地帯を指す地域名。東京都西多摩郡奥多摩町を中心とするが、周辺の山域も含む。","img":"Mts.Okutama%20from%20Daibosatsu-Pass%2001.jpg","k":"山々","m":4,"hi":"鷹ノ巣山","he":1737},{"n":"八甲田山","q":"Q3047571","wp":"八甲田山","pts":[[40.6185,140.8417],[40.656,140.8922]],"d":"八甲田山（はっこうださん）は、青森市の南側にそびえる大岳（標高1,584m）を主峰とする18の山々からなる複数火山の総称。日本百名山の一つ。","img":"Suiren%20Pond%20and%20the%20Hakk%C5%8Dda%20Mountains%20late%20autumn.jpg","k":"山々","m":4,"hi":"高田大岳","he":1559},{"n":"丹生山系","q":"Q6130157","wp":"丹生山系","pts":[[34.7834,135.1064],[34.7836,135.14]],"d":"丹生山系（たんじょうさんけい / みぶさんけい）は、兵庫県南東部に位置する山地。六甲山系と共に六甲山地を形成するとされることもある。丹生・帝釈山系とも呼ばれる。","img":"Tanjosankei01.JPG","k":"山系","m":4,"hi":"稚児ヶ墓山","he":596},{"n":"朝日山地","q":"Q11517486","wp":"朝日山地","pts":[[38.3579,139.7829],[38.2122,140.0004]],"d":"朝日山地（あさひさんち）は、新潟県と山形県の県境に位置する山地。 広義には朝日山地の西縁として日本海側の海岸部の北側にある摩耶山地や蒲萄山地を含める。一方で朝日山地、摩耶山地、蒲萄山地を分けた上で3列の総称を朝日山系とする資料もある。朝日山地は朝日連峰と呼ぶこともある。","img":"Asahi%20Mountains%202011-06-25.jpg","k":"山地","m":4,"hi":"化穴山","he":1506},{"n":"八溝山地","q":"Q11391525","wp":"八溝山地","pts":[[36.3126,140.1364],[36.8214,140.2826]],"d":"八溝山地（やみぞさんち）は、福島県白河市南部から茨城県と栃木県の県境付近を南下し、筑波山に至る山地。福島県東白川郡棚倉町と茨城県久慈郡大子町に跨がって座す八溝山を主峰とする。阿武隈高地とは棚倉構造線によって生じた地溝を流れ下る久慈川によって隔てられる。かつては広義の阿武隈高地に含めることもあったが、今日では別のものと考えられている。","img":"Yamizo%20Mountains%20from%20Mt.Shakujo%2002.jpg","k":"山地","m":4,"hi":"八溝山","he":1022},{"n":"身延山地","q":"Q11637225","wp":"身延山地","pts":[[35.3804,138.3828],[35.2506,138.4021]],"d":"身延山地（みのぶさんち）は、山梨県南西部と静岡県北部にまたがる山地。広い意味での赤石山脈(赤石山系)に属するが、赤石山脈に身延山地を含めない場合もある。東側には富士川を隔てて天子山地がある。 一般的には、早川の谷から南側、富士川右岸の山地をさすと考えられるが、早川の谷の北側に連なる巨摩山地を含める場合もあり、また安倍川右岸の山を含むのか否かなど、境界ははっきりしない点もある。","img":null,"k":"山地","m":4,"hi":"七面山","he":1989},{"n":"阿寺山地","q":"Q11657388","wp":"阿寺山地","pts":[[35.7939,137.3656],[35.6779,137.4867]],"d":"阿寺山地（あてらさんち）は、岐阜県と長野県にまたがって、北西-南東方向にほぼ一直線に連なっている。これは、活断層である阿寺断層に起因するものである。木曽川水系の付知川や白川、阿寺川などの源流となる山地である。 御嶽山の南に位置し、藪山となっている場合を除き、多くの山の頂上からは、御嶽山を望むことが出来る。","img":"Mount%20Okusangai%20and%20Mount%20Ontake%20from%20Mount%20Nagiso%202011-02-13.jpg","k":"山地","m":4,"hi":"小秀山","he":1982},{"n":"高野山","q":"Q535065","wp":"高野山","pts":[[34.2281,135.5894],[34.2039,135.6347]],"d":"高野山（こうやさん）は、和歌山県北部、和歌山県伊都郡高野町にある地域の名称である。周囲を1,000m級の山々に囲まれた標高約800mの山上盆地に町並みが広がる。 「高野\"山\"」という名ではあるものの、地理学上の山ではない。高野山内は「一山境内地」といわれ高野山全域が寺の境内地とされ、境内の中に発展した町であり、元来は高野山全体と金剛峯寺は同義である。","img":"Danjogaran%20Koyasan12n3200.jpg","k":"山々","m":3,"hi":null,"he":null},{"n":"布引山地","q":"Q11480794","wp":"布引山地","pts":[[34.5481,136.2173],[34.7131,136.4001]],"d":"布引山地（ぬのびきさんち）は、三重県中部を南北に連なる山塊の総称。亀山市から津市西方を南北に延びる標高700 - 800 mのなだらかな山地で、伊勢平野とは布引山地東縁断層帯を境として接している。最高峰は南部に位置する大洞山（標高985 m)である。北は鈴鹿山脈、南は高見山地に接する。","img":"Mount%20Obora%20Tsu.jpg","k":"山地","m":3,"hi":"尼ヶ岳","he":957},{"n":"養老山地","q":"Q8062668","wp":"養老山地","pts":[[35.2734,136.5173],[35.1446,136.6256]],"d":"養老山地（ようろうさんち）は、岐阜県と三重県にまたがる濃尾平野の西端にある傾動地塊の山地。最高峰は北部の標高908.2 mの笙ヶ岳。最南端に多度山（標高402.7 m）がある。 山域は岐阜県大垣市上石津町、養老郡養老町、海津市南濃町、三重県いなべ市（北勢町、藤原町、員弁町）、桑名市多度町の自治体にまたがる。","img":"Yorosan%20from%20the%20foot%20in%20mountain%202008%2004%2020.jpg","k":"山地","m":3,"hi":"笙ヶ岳","he":908},{"n":"阿武隈高地","q":"Q9283820","wp":"阿武隈高地","pts":[[37.4883,140.6124],[36.6211,140.5878]],"d":"阿武隈高地（あぶくまこうち）は、宮城県南部から茨城県北部にかけて広がっている高地で、大部分が福島県に属している。阿武隈山地（あぶくまさんち）とも呼ばれる。","img":"AbukumaKohchiViewFromIshikawa.jpg","k":"高地","m":3,"hi":"矢大臣山","he":965},{"n":"八ヶ岳連峰","q":"Q11390433","wp":"八ヶ岳連峰","pts":[[36.1102,138.2344],[35.995,138.3628]],"d":"八ヶ岳連峰（やつがたけれんぽう）は、長野県諏訪地域・佐久地域と山梨県にまたがる山塊。赤岳、横岳といった八ヶ岳の主峰部分から蓼科山まで南北30km余りの山体で、大火山群である。 単に、八ヶ岳と言った場合は、山塊である八ヶ岳連峰を指す場合と、最高峰の赤岳を中心とした南八ヶ岳の山体を指す場合などがある。詳しくは八ヶ岳の項目を参照。","img":"Mount%20Yatsu.JPG","k":"連峰","m":3,"hi":null,"he":null},{"n":"御坂山地","q":"Q11488873","wp":"御坂山地","pts":[[35.507,138.6994],[35.5565,138.7636]],"d":"御坂山地（みさかさんち）は山梨県南部、甲府盆地と富士山北麓及び桂川（相模川）流域との間に東西に延びる山地。東から高川山（976m）、三つ峠（1,785m）、御坂山（1,596m）、黒岳（1,793m）、節刀ヶ岳（1,736m）等の山が有る。御坂山近くに御坂峠が有り、甲府盆地と富士五湖がある郡内地方を結ぶ。北東の笹子峠で奥秩父山塊の大菩薩連嶺の山系に接続する。","img":"Lake%20Sh%C5%8Dji%20from%20Panoramadai.JPG","k":"山地","m":3,"hi":"十二ヶ岳","he":1683},{"n":"御嶽山系","q":"Q11488962","wp":"御嶽山系","pts":[[35.7856,137.3969],[35.8818,137.4922]],"d":"御嶽山系（おんたけさんけい）は、岐阜県と長野県にまたがる山系。御嶽山及び周辺の山々と、阿寺山地からなる。おおよそ、木曽川と飛騨川及び付知川・白川で囲まれた山域で、面積は1,000km²を超える。国道19号、257号、41号、361号の内側の山域とも言える。","img":"Mount%20Okusangai%20and%20Mount%20Ontake%20from%20Mount%20Nagiso%202011-02-13.jpg","k":"山系","m":3,"hi":"御嶽山","he":3067},{"n":"果無山脈","q":"Q11533512","wp":"果無山脈","pts":[[33.8987,135.6385],[33.8978,135.6878]],"d":"果無山脈（はてなしさんみゃく）は、和歌山県と奈良県の県境沿いに位置する山脈。最高地点は冷水山（1262メートル）。和歌山県側の一部は果無山脈県立自然公園に指定されている。","img":null,"k":"山脈","m":3,"hi":null,"he":null},{"n":"毛勝三山","q":"Q11547717","wp":"毛勝三山","pts":[[36.6853,137.5882],[36.7011,137.5911]],"d":"毛勝三山（けかちさんざん）は、富山県魚津市と黒部市の間にある山岳群である。飛騨山脈立山連峰の北に連なり、毛勝山・釜谷山・猫又山で構成。この三山は、片貝川の源流でもある。登山道については後述。","img":"Kekati.jpg","k":"山々","m":3,"hi":null,"he":null},{"n":"高原山","q":"Q11668908","wp":"高原山","pts":[[36.8991,139.7702]],"d":"高原山（たかはらやま、たかはらさん）は、栃木県日光市と同塩谷郡塩谷町、那須塩原市、矢板市にまたがる山である。特に主峰鶏頂山、釈迦ヶ岳、中岳、西平岳の山頂部は日光市と塩谷町に在り、東北部の裾野である八方ヶ原も含め、その山体は日光国立公園に在る。日本三百名山の一つに選定されている。","img":"TakaharaSan.JPG","k":"山々","m":2,"hi":null,"he":null},{"n":"鰐塚山地","q":"Q11674317","wp":"鰐塚山地","pts":[[31.7981,131.3758]],"d":"鰐塚山地（わにつかさんち）は、九州南東部の太平洋沿岸において直径約40キロメートルの範囲に広がる山地である。南那珂山地（みなみなかさんち）、あるいは日南山地（にちなんさんち）とも呼ばれる。北東部海岸沿いの清武川と広渡川に挟まれた山塊は特に鵜戸山地（うとさんち）と呼ばれる。","img":"Wanitsukayama%20from%20Tano%20Japan.jpg","k":"山地","m":2,"hi":"双石山","he":509},{"n":"飯能アルプス","q":"Q30935254","wp":"飯能アルプス","pts":[[35.8619,139.3083]],"d":"飯能アルプス（はんのうアルプス）は、一般的に埼玉県の天覧山（標高197m）から、伊豆ヶ岳（標高850.9m）へと続く稜線の山々。伊豆ヶ岳からさらに武甲山（1304m）までの山々を指すこともある。","img":null,"k":"山々","m":2,"hi":"多峰主山","he":271},{"n":"大佐渡山地","q":"Q86734482","wp":"大佐渡山地","pts":[[38.1039,138.3497]],"d":"大佐渡山地（おおさどさんち）は、佐渡島の北半部を占める地塁山地。南南西から北北東に伸びており、主稜線の標高は約600 - 1,100メートル。 国中平野をはさんで小佐渡山地（小佐渡丘陵）と対している。 中間部には佐渡島最高峰の金北山（1,172メートル）がある。","img":"Kimpokusan%20and%20Kamoko.jpg","k":"山地","m":2,"hi":"金北山","he":1171},{"n":"三郡山地","q":"Q97195125","wp":"三郡山地","pts":[[33.5561,130.5828]],"d":"三郡山地（さんぐんさんち）は、九州北部の福岡県に位置する山地である。筑紫山地の一部で、最高峰は標高936m（正確には935.9m）の三郡山。","img":null,"k":"山地","m":2,"hi":"三郡山","he":936},{"n":"海部山地","q":"Q109599159","wp":"海部山地","pts":[[33.6972,134.1608]],"d":"海部山地（かいふさんち）は四国山地東部に属する赤城尾山を最高峰とする山地である。","img":null,"k":"山地","m":2,"hi":"甚吉森","he":1423},{"n":"筑波山地","q":"Q11602874","wp":"筑波山地","pts":[[36.2258,140.105]],"d":"筑波山地（つくばさんち）は、茨城県の中西部にある山地。筑波山塊（つくばさんかい）ともいう。","img":"Tsukuba%20Mountains%20from%20Sakuragawa%20City%2001-2.jpg","k":"山地","m":2,"hi":"筑波山","he":877},{"n":"野坂山地","q":"Q11645276","wp":"野坂山地","pts":[[35.5967,136.1061]],"d":"野坂山地（のさかさんち）は、滋賀県と福井県若狭地方に跨がる山地。琵琶湖国定公園特別保護地区。 地質的には江若（こうじゃく）花崗岩類と呼ばれる花崗岩類が広く分布する。 若狭と京都を結ぶ交通の要衝で、古くは愛発関が置かれていた。","img":null,"k":"山地","m":2,"hi":"三内山","he":521},{"n":"医王山","q":"Q11404619","wp":"医王山","pts":[[36.5267,136.7528]],"d":"医王山（いおうぜん）は、石川県金沢市と富山県南砺市にまたがる標高939mの山塊である。白兀山、奥医王山及び前医王山などの山塊の総称で、最高点の奥医王山には一等三角点が設置されている。日本三百名山及び新・花の百名山に選定されている。","img":"Mt%20Iwozen%20from%20Kanazawa%20Castle.jpg","k":"山々","m":2,"hi":null,"he":null},{"n":"多賀山地","q":"Q11431076","wp":"多賀山地","pts":[[36.6349,140.6087]],"d":"多賀山地（たがさんち）とは、茨城県北東部に広がる阿武隈高地の南部の名称である。","img":null,"k":"山地","m":2,"hi":"高鈴山","he":623},{"n":"嶺岡山地","q":"Q6864195","wp":"嶺岡山地","pts":[[35.1147,139.9867]],"d":"嶺岡山地（みねおかさんち、英:Mineoka Mountains）とは、千葉県南部の房総半島にある房総丘陵のうち、加茂川以南の嶺岡愛宕山･嶺岡浅間などの山々を指す。嶺岡山系（みねおかさんけい）とも呼ばれている。県立嶺岡山系自然公園に指定されている。 一般に嶺岡山（みねおかやま、峯岡山）と呼ばれるのは嶺岡愛宕山を中心とした連峰を指し、特定の山を指す呼称ではない。","img":"Mineoka-atagoyama.jpg","k":"山地","m":2,"hi":"愛宕山","he":408},{"n":"帝釈山脈","q":"Q11481091","wp":"帝釈山脈","pts":[[37.0361,139.6436]],"d":"帝釈山脈（たいしゃくさんみゃく）は、福島県南西部と栃木県北西部の境にあり、一部が群馬県にかかる山地。広義の越後山脈に入る。会津経由で新潟に向かう阿賀川の流域と関東平野を流れて利根川へとつながる鬼怒川の流域の境界にある。近辺には他に多数の山地があり、しかも帝釈山脈と同程度、もしくはさらに高いものも多い（帝釈山脈で最も高い黒岩山が2163m、これに対し、例えば燧ヶ岳は2356m）ため、低地からはほとんど見ることができない。","img":null,"k":"山脈","m":2,"hi":"荒海山","he":1581},{"n":"狩場山地","q":"Q11571425","wp":"狩場山地","pts":[[42.6358,140.1356]],"d":"狩場山地（かりばさんち）は、渡島半島北部をほぼ東西に走る山地である。後志利別川北側を走っており、後志総合振興局、檜山振興局、渡島総合振興局に跨っている。 一帯は、狩場茂津多道立自然公園に指定されている。 また、狩場山地西部は、狩場山自然休養林、東部は美利河・二股自然休養林に指定されている。","img":"Karibayama01.jpg","k":"山地","m":2,"hi":"大平山","he":1191},{"n":"真昼山地","q":"Q11583207","wp":"真昼山地","pts":[[39.4478,140.6765]],"d":"真昼山地（まひるさんち）は、岩手県と秋田県の県境のほぼ中央部にまたがる山地。","img":"%E7%9C%9F%E6%98%BC%E5%B2%B3.JPG","k":"山地","m":2,"hi":"真昼岳","he":1059},{"n":"篠井富屋連峰","q":"Q11603531","wp":"篠井富屋連峰","pts":[[36.5702,139.8872]],"d":"篠井富屋連峰（しのいとみやれんぽう）は、栃木県宇都宮市北部山系を成す山域の総称である。南東側に田川、北西側に鬼怒川が流れ、両川に挟まれた形で山地が形成されている。宇都宮アルプスと呼ばれることもある。","img":null,"k":"連峰","m":2,"hi":"八幡山","he":159},{"n":"白山連峰","q":"Q11579613","wp":"白山連峰","pts":[[36.1,136.5]],"d":"白山連峰（はくさんれんぽう）は、岐阜県と、富山県、石川県、福井県にまたがる山域。","img":null,"k":"連峰","m":1,"hi":"白山","he":2702},{"n":"蔵王連峰","q":"Q167951","wp":"蔵王連峰","pts":[[38.041,140.5303]],"d":"蔵王連峰（ざおうれんぽう）は、東北地方の中央を南北に連なる奥羽山脈の中にあって、宮城県と山形県の両県南部の県境に位置する連峰。奥羽山脈において時と場所を移しながら次々と繰り返された火山活動によって形成された複合火山群である。 玄武岩、安山岩の成層火山群の活火山であり、気象庁の常時観測火山に含まれている。火口湖である御釜や噴気口が見られる。","img":"Mount%20Za%C5%8D%20and%20Sakura%2001.jpg","k":"連峰","m":1,"hi":null,"he":null},{"n":"高隈山地","q":"Q11673198","wp":"高隈山地","pts":[[31.4603,130.8206]],"d":"高隈山地（たかくまさんち）は、大隅半島中央部の鹿児島湾沿いに連なる山地である。一般には鹿児島県鹿屋市と垂水市との境界付近に横たわる南北約25km、東西約15kmの山地を指し、その中心部にそびえる大箆柄岳や御岳などを含む標高1,000m以上の山岳群を総称して高隈山（たかくまやま）と呼ぶ。 日本におけるブナ林の南限があり、「森林生物遺伝資源保存林」に指定されている。また、高峠、大隅湖、猿ヶ城渓谷などの景勝地は「高隈山県立自然公園」に指定されている。","img":"%E4%B8%B2%E8%89%AF%E7%94%BA%E6%9C%89%E9%87%8C%E3%81%8B%E3%82%89%E7%9C%BA%E3%82%81%E3%82%8B%E9%AB%98%E9%9A%88%E5%B1%B1.JPG","k":"山地","m":1,"hi":null,"he":null},{"n":"和賀山塊","q":"Q17216189","wp":"和賀山塊","pts":[[39.5703,140.7542]],"d":"和賀山塊（わがさんかい）は、秋田・岩手県境にある山塊。奥羽山脈真昼山地の一部。奥深い原生自然とブナ混生林、さらに巨樹・巨木の存在によって知られている。","img":"%E5%92%8C%E8%B3%80%E5%B1%B1%E5%A1%8A.jpg","k":"山々","m":1,"hi":null,"he":null},{"n":"耳納山地","q":"Q11610738","wp":"耳納山地","pts":[[33.2979,130.5746]],"d":"耳納山地（みのうさんち）は、福岡県筑後地方にある山地名。水縄山地とも表記する。耳納連山（みのうれんざん）の通称もある。","img":"Chikugogawa%20River%20from%20Miyanojimbashi%20Bridge%20%28east%29.JPG","k":"山地","m":1,"hi":"高良山","he":312},{"n":"諭鶴羽山地","q":"Q11632032","wp":"諭鶴羽山地","pts":[[34.2349,134.8142]],"d":"諭鶴羽山地（ゆづるはさんち）は、兵庫県の淡路島南部を北東から南西に連なる山地。最高峰は諭鶴羽山（ゆづるはさん、607.9m）。一部が瀬戸内海国立公園に属している。","img":"Yuzuruha%20Mts%201.jpg","k":"山地","m":1,"hi":"諭鶴羽山","he":608},{"n":"宝達丘陵","q":"Q11452693","wp":"宝達丘陵","pts":[[36.7819,136.813]],"d":"宝達丘陵（ほうだつきゅうりょう）は、能登半島の基部に位置する丘陵地帯である。石川県と富山県にまたがっており、海抜500 m以上の山も見られ、宝達山地とも呼ぶこともある。両県境に沿う山地・丘陵のうち、概ね倶利伽羅峠付近以北を指し、南は両白山地（加越山地）に連なる。","img":"Mount%20Hodatsu%2001.jpg","k":"丘陵","m":1,"hi":"宝達山","he":637},{"n":"室生火山群","q":"Q11453042","wp":"室生火山群","pts":[[34.5379,136.0406]],"d":"室生火山群（むろうかざんぐん）とは、奈良県宇陀市東北部および宇陀郡曽爾村、御杖村全域から三重県名張市南部にかけて広がる山地。約1500万年前の火山活動によって出来た山々が連なる。室生山地とも。全域が室生赤目青山国定公園に含まれる。","img":"Nara%20soni%20byoubuiwa.JPG","k":"山々","m":1,"hi":null,"he":null},{"n":"法皇山脈","q":"Q8350971","wp":"法皇山脈","pts":[[33.9428,133.5361]],"d":"法皇山脈（ほうおうさんみゃく）は、石鎚山脈のうち、中央部に位置する笹ヶ峰の東部、「ちち山別れ」とよばれる地点より分岐し、瀬戸内海沿いに東へと延びる、石鎚山脈の一部である 。","img":"Suiha07.jpg","k":"山脈","m":1,"hi":"翠波峰","he":900},{"n":"白馬山脈","q":"Q10430567","wp":"白馬山脈","pts":[[34.0,135.3667]],"d":"白馬山脈（しらまさんみゃく）は紀伊山地に属する和歌山県の山脈の一つ。 護摩壇山から有田川と日高川の間を東西に走り、紀伊半島最西端の日ノ岬に至る。","img":null,"k":"山脈","m":1,"hi":null,"he":null},{"n":"金峰山","q":"Q10563986","wp":"金峰山","pts":[[34.3684,135.8581]],"d":"金峰山（きんぷせん）とは、奈良県の大峰山脈のうち吉野山から山上ヶ岳までの連峰の総称。または山上ヶ岳の別称である。金峯山とも表記する。修験道発祥の山であるが、金峰山の境域は必ずしも明確ではない。","img":"Otenjodake05.JPG","k":"山々","m":1,"hi":null,"he":null},{"n":"丹生山地","q":"Q11368594","wp":"丹生山地","pts":[[36.08,136.0851]],"d":"丹生山地（にうさんち）は、福井県嶺北に位置する山地。嶺北、九頭竜川水系流域と越前海岸を隔てる。 一部は越前加賀海岸国定公園の区域である。","img":"Nyuu%20place.JPG","k":"山地","m":1,"hi":"国見岳","he":656},{"n":"出水山地","q":"Q11395674","wp":"出水山地","pts":[[31.9808,130.3678]],"d":"出水山地（いずみさんち）は、九州南西部海岸沿いにおいて東西約30キロメートル、南北約15キロメートルの範囲に横たわる山地である。紫尾山地（しびさんち）とも呼ばれる。北側には出水平野および肥薩火山群、南東側には北薩火山群および宮之城盆地、南西側には川内平野を配しており、西側は東シナ海に面している。鹿児島県出水市、伊佐市、さつま町、薩摩川内市、阿久根市にまたがる。","img":"Shibisan%20from%20Miyanojo.JPG","k":"山地","m":1,"hi":"紫尾山","he":1067},{"n":"弓張山地","q":"Q11487100","wp":"弓張山地","pts":[[34.8496,137.5872]],"d":"弓張山地（ゆみはりさんち）は、赤石山脈の南側の愛知県豊橋市・新城市と静岡県湖西市・浜松市浜名区 にまたがる山地。八名弓張山地（やなゆみはりさんち）とも呼ばれる。","img":null,"k":"山地","m":1,"hi":"富幕山","he":563},{"n":"恐山山地","q":"Q11492160","wp":"恐山山地","pts":[[41.2931,141.0683]],"d":"恐山山地（おそれざんさんち）は、青森県下北半島に位置する山地。釜臥山を主とする火山群地域である。","img":null,"k":"山地","m":1,"hi":"大尽山","he":827},{"n":"戸隠連峰","q":"Q11496666","wp":"戸隠連峰","pts":[[36.8,138.0519]],"d":"戸隠連峰（とがくしれんぽう）は、新潟県と長野県に跨る山域で、戸隠表山と戸隠裏山からなる。その多くが妙高戸隠連山国立公園に含まれる。 東側には独立峰である黒姫山があり、西側には姫川を挟んで後立山連峰と対峙している。","img":"%E7%91%AA%E7%91%99%E5%B1%B1%E3%81%8B%E3%82%89%E8%A6%8B%E3%81%9F%E6%88%B8%E9%9A%A0%E9%80%A3%E5%B3%B0.jpg","k":"連峰","m":1,"hi":"高妻山","he":2353},{"n":"御荷鉾山系","q":"Q11489305","wp":"御荷鉾山系","pts":[[36.1528,138.9194]],"d":"御荷鉾山系（みかぼさんけい）は、群馬県南西部にある山系であり、上武山地の群馬県側を形成する。山中を御荷鉾スーパー林道が東西に貫く。","img":null,"k":"山系","m":1,"hi":"御荷鉾山","he":1286},{"n":"足柄山地","q":"Q11636900","wp":"足柄山地","pts":[[35.2897,139.0047]],"d":"足柄山地（あしがらさんち）は、神奈川県西部の足柄地域から静岡県東部の駿東郡小山町にかけて広がる山地である。","img":"Ashigara%20Mountains%2004.jpg","k":"山地","m":1,"hi":"金時山","he":1212},{"n":"秋田駒ヶ岳","q":"Q419247","wp":"秋田駒ヶ岳","pts":[[39.7608,140.8036]],"d":"秋田駒ヶ岳（あきたこまがたけ）は、秋田県仙北市と岩手県岩手郡雫石町に跨る活火山。南西側と北東側に異なる火口（噴出中心）をもつ複合火山である。標高1,637m。十和田八幡平国立公園の南端に位置する。","img":"Mount%20Akita-Komagatake%20seen%20from%20Lake%20Tazawa%2020210213.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"五段高原","q":"Q21653044","wp":"五段高原","pts":[[33.4725,132.9875]],"d":"五段高原（ごだんこうげん）は、四国山地の南西部、「四国カルスト」と呼ばれるカルスト高原のうち、中部から東部にかけての、標高1,300 - 1,450メートルほどの高原状の地域を指す地名である。「四国百名山」35番に選定されている。 当地は行政区画的には、その東西方向に延びる稜線部の北側が愛媛県 久万高原町に属し、稜線部の南側は、高知県 梼原町（ゆすはらちょう）と、高知県 津野町（つのちょう）に属する。牛の放牧場にもなっていて草原状となっていることから、後述の通り、典型的な「カルスト地形」が見られる。","img":"Godankougen05.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"三井野原","q":"Q65247847","wp":"三井野原","pts":[[35.0935,133.1184]],"d":"三井野原（みいのはら）は、島根県奥出雲町にある高原。","img":null,"k":"山々","m":0,"hi":null,"he":null},{"n":"肝属山地","q":"Q11611497","wp":"肝属山地","pts":[[31.2642,130.99]],"d":"肝属山地（きもつきさんち）は、九州南部の大隅半島南端部に横たわる山地である。国見山地（くにみさんち）などとも呼ばれる。北東から南西の方向に約50 kmの長さがある。山地の北側には肝属平野が広がり、北東側は志布志湾、南東側は大隅海峡（太平洋）、西側は鹿児島湾に面している。","img":null,"k":"山地","m":0,"hi":null,"he":null},{"n":"那智山","q":"Q11642744","wp":"那智山 (山)","pts":[[33.6833,135.8833]],"d":"那智山（なちさん）は和歌山県那智勝浦町北東部の内陸一帯にそびえる山々の総称。 名称の由来は、難地の義とも、熊野本宮大社や熊野速玉大社よりもノチ（後）に山が開かれたからともいわれるが定かではない。世界遺産・紀伊山地の霊場と参詣道の登録物件が所在する。","img":null,"k":"山々","m":0,"hi":null,"he":null},{"n":"琴平山","q":"Q11573769","wp":"琴平山 (香川県)","pts":[[34.1861,133.8025]],"d":"琴平山（ことひらやま）は、香川県のうち善通寺市（ぜんつうじし）、琴平町（ことひらまち）、三豊市（みとよし）にまたがり、山全体は「大麻山」（おおさやま）あるいは「象頭山」（ぞうずさん）と呼ばれる標高；616ｍの山のうち、南側の標高524ｍのピーク、およびその一帯の呼び名である。","img":"Enai%20stn.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"妙義山","q":"Q994071","wp":"妙義山","pts":[[36.2986,138.7347]],"d":"妙義山（みょうぎさん）は、群馬県甘楽郡下仁田町・富岡市・安中市の境界に位置する山域の総称。赤城山や榛名山と共に上毛三山の一つとされ、日本三大奇景の一つにも数えられる山である。 山域のほとんどは妙義荒船佐久高原国定公園の区域内で、金洞山南東麓の石門群で知られる奇勝部分（群馬県県有地）が群馬県立妙義公園となっている。","img":"Mt-myogi-in-summer.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"大佐飛山地","q":"Q11432373","wp":"大佐飛山地","pts":[[37.0636,139.8444]],"d":"大佐飛山地（おおさびさんち）は栃木県北部にあり、那須連山と高原山にはさまれた山地。大佐飛山（1908m）を主峰とし、帝釈山脈と共に下野山地を形成する山塊の一つである。","img":null,"k":"山地","m":0,"hi":null,"he":null},{"n":"宇陀山地","q":"Q11449915","wp":"宇陀山地","pts":[[34.4969,135.9703]],"d":"宇陀山地（うださんち）とは、奈良県内にある宇陀市南部に広がる山地。宇陀市と宇陀郡曽爾村、御杖村を含む宇陀地域全域の山地を指すこともあり、この場合は高見山地（奥宇陀山地）、室生山地の一部も宇陀山地に含まれる。逆に宇陀山地全域を室生山地の一部と見なす場合もある。また標高300メートルから500メートルの口宇陀盆地は高原ともいえ北部、笠置山地に広がる大和高原に含まれる場合もある。","img":"Udasanchi20101002.JPG","k":"山地","m":0,"hi":null,"he":null},{"n":"榛名山","q":"Q1191690","wp":"榛名山","pts":[[36.4769,138.8781]],"d":"榛名山（はるなさん）は、関東平野の北西端、群馬県のほぼ中央に位置する山。上毛三山の一つである。古来山岳信仰を受けてきた山で、山の南西麓に榛名神社が祀られている。","img":"Mount%20Haruna%20view%20from%20Hokkitsu%20Onsen%20Tachibana%20no%20sato%20Shiroyama.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"万年山","q":"Q11353823","wp":"万年山","pts":[[33.2314,131.1308]],"d":"万年山（はねやま）は、大分県日田市、玖珠郡玖珠町、九重町にまたがり、耶馬日田英彦山国定公園に含まれる標高1,140.3mの山である。","img":"Mt.Haneyama.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"二上山","q":"Q11371271","wp":"二上山 (奈良県・大阪府)","pts":[[34.5256,135.6775]],"d":"二上山（にじょうさん）は、奈良県葛城市と大阪府南河内郡太子町にまたがる山。かつては大和言葉による読みで「ふたかみやま」と呼ばれた。金剛山地北部に位置し、北方の雄岳 (517m) と南方の雌岳 (474m) の2つの山頂がある双耳峰で、大阪みどりの百選に選定されている。また、石器に使われた讃岐岩（サヌカイト）の産地である。","img":"Mt.Nijyo.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"オプタテシケ山","q":"Q6922598","wp":"オプタテシケ山","pts":[[43.4703,142.7517]],"d":"オプタテシケ山（オプタテシケやま）は北海道上川郡美瑛町と新得町の境界に位置する標高2,013mの山である。三等三角点の名称は「美瑛岳」と記されている。","img":"Oputateshikeyama%20and%20Bieifuji%20from%20Bieidake%202005-8-15.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"多紀連山","q":"Q10872066","wp":"多紀連山","pts":[[35.125,135.2417]],"d":"多紀連山（たきれんざん）は、京都府から丹波篠山市、丹波市にかけて高い岸壁状に連なる500m～700mの山々の総称で、旧多紀郡にちなみ多紀アルプスとも呼ばれる。主峰は御嶽（793m）で西ヶ嶽（727m）、小金ヶ嶽（725m）の3つの峰が中心となっている。","img":null,"k":"山々","m":0,"hi":null,"he":null},{"n":"丹後山地","q":"Q11368520","wp":"丹後山地","pts":[[35.4075,134.9031]],"d":"丹後山地（たんごさんち）は、京都府北部から兵庫県北部にかけて広がる山地である。丹波高地の北西部に相当し、国土地理院では丹後山地の山々は丹波高地と分類している。由良川および円山川に挟まれた領域で、南端は福知山盆地（牧川）に接する。また東部の丹後半島部分は竹野川により隔てられる。","img":"Tango%20mountains1.jpg","k":"山地","m":0,"hi":null,"he":null},{"n":"千畳敷","q":"Q11405754","wp":"千畳敷 (山口県)","pts":[[34.4145,131.0902]],"d":"千畳敷（せんじょうじき）は、山口県長門市日置中に位置する草原・台地。","img":"%E9%95%B7%E9%96%80%E5%8D%83%E7%95%B3%E6%95%B7.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"御津山脈","q":"Q11489192","wp":"御津山脈","pts":[[34.7833,134.5017]],"d":"御津山脈（みつさんみゃく）は、兵庫県たつの市御津町 - 相生市鰯浜間を走る山脈。最高峰は雄鷹台山の310mである。 瀬戸内海に面しており、瀬戸内海国立公園の一部を成す。家島諸島と素晴しい景観を生んでいるとされている。","img":null,"k":"山脈","m":0,"hi":null,"he":null},{"n":"揖宿山地","q":"Q11498401","wp":"揖宿山地","pts":[[31.4678,130.3833]],"d":"揖宿山地（いぶすきさんち）は、鹿児島県の薩摩半島中部から南部にかけて広がる山地である。","img":null,"k":"山地","m":0,"hi":null,"he":null},{"n":"東丹沢","q":"Q11523895","wp":"東丹沢","pts":[[35.4842,139.2125]],"d":"東丹沢（ひがしたんざわ）は、神奈川県北西部に広がる丹沢山地の東側地域の通称である。西側地域の西丹沢はニシタンの愛称で親しまれているが、東丹沢においてはそのような愛称は存在しない。","img":"Tanzawa%20Mountains%20from%20Mt.Bukka%2001.jpg","k":"山々","m":0,"hi":null,"he":null},{"n":"櫛形山脈","q":"Q11544681","wp":"櫛形山脈","pts":[[38.0222,139.4278]],"d":"櫛形山脈（くしがたさんみゃく）は、新潟県胎内市から新発田市にかけての山脈。","img":null,"k":"山脈","m":0,"hi":null,"he":null},{"n":"津軽山地","q":"Q11556405","wp":"津軽山地","pts":[[41.1528,140.5864]],"d":"津軽山地（つがるさんち）は、青森県津軽半島を北西から南南東方向にのびる脊梁山地。3つに区分される山塊の総称である。","img":null,"k":"山地","m":0,"hi":null,"he":null},{"n":"小野アルプス","q":"Q72166150","wp":"小野アルプス","pts":[[34.8253,134.9]],"d":"小野アルプス（おのアルプス）は、兵庫県小野市と加古川市の境界を成す山並。ご当地アルプスの一つ。 おおよそ東西4 kmに亘って標高100 - 200 mの山々が連なる。縦走すると約15.1 kmで、5時間で踏破できる。","img":null,"k":"山々","m":0,"hi":null,"he":null},{"n":"幌内山地","q":"Q139001784","wp":"幌内山地","pts":[[43.6061,142.27]],"d":"幌内山地（ほろないさんち）は、北海道中央西部を走る山地であり、上川総合振興局と空知総合振興局にまたがる。石狩山地の十勝岳から美瑛町と上富良野町の境界がある尾根で繋がっており、北側は石狩川上流、南側は空知川に挟まれた分水嶺となっている。 新城峠を経て西側は音江連山と呼ばれ、イルムケップ山を最高峰とする約250万年前に活動したとされる成層火山となっている。 かつては函館本線納内駅と根室本線芦別駅を繋ぎ幌内山地を縦断する芦別線が計画されていたが、未成に終わっている。","img":null,"k":"山地","m":0,"hi":null,"he":null}];
